ng-progress">@foreach($stages as $key=>$label)<li class="{{ $position!==false && $loop->index<=$position?'done':'' }}"><span>{{ $position!==false && $loop->index<$position?'✓':$loop->iteration }}</span><small>{{ $label }}</small></li>@endforeach</ol><div class="panel-heading"><div><p class="eyebrow">LATEST UPDATES</p><h3>Every milestone, in order.</h3></div><span class="subtle-tag">Times in UTC</span></div><ol class="shipment-timeline">@forelse($events as $event)<li><span class="timeline-node {{ $loop->first?'current':'' }}"></span><div><strong>{{ Status::label($event->status) }}</strong><p>{{ $event->description }}</p><small>{{ $event->location }}</small><time>{{ $event->timestamp?->format('M d, Y · H:i') }} UTC</time></div></li>@empty<li><p>Updates will appear after the first scan.</p></li>@endforelse</ol></section>@else<div class="tracking-empty"><div class="service-icon"><svg viewBox="0 0 32 32" fill="none"><path d="m5 9 11-6 11 6-11 6L5 9Zm0 0v14l11 6 11-6V9M16 15v14"/></svg></div><h2>A window into your shipment.</h2><p>Enter your ShipFast tracking number to see the latest recorded status, estimated arrival and milestone history.</p></div>@endif</section>
